class Solution {
  public long minIncrease(int[] nums) {
    int n = nums.length;
    long[] cost = new long[n];
    for (int i = 1; i + 1 < n; i++)
      cost[i] = Math.max(0, Math.max(nums[i - 1], nums[i + 1]) + 1L - nums[i]);
    int picks = (n - 1) / 2;
    // picks at positions 1, 3, ... shifted by one after some switch point (only possible when n is
    // even)
    long[] oddPrefix = new long[picks + 1];
    for (int j = 1; j <= picks; j++) oddPrefix[j] = oddPrefix[j - 1] + cost[2 * j - 1];
    long[] shiftedSuffix = new long[picks + 2];
    if (n % 2 == 0) {
      for (int j = picks; j >= 1; j--) shiftedSuffix[j] = shiftedSuffix[j + 1] + cost[2 * j];
    }
    if (n % 2 == 1) return oddPrefix[picks];
    long best = Long.MAX_VALUE;
    for (int t = 0; t <= picks; t++) best = Math.min(best, oddPrefix[t] + shiftedSuffix[t + 1]);
    return best;
  }
}
